//-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
//	NAME:			HE_StateControl
//	CREATOR:		Helgevold - William Veim
// 
//-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
//  VERSION LOG:
//	VERSION			DATE					SIGN							DESCRIPTION
//	1.0.0					2025-03-27			William Veim				Initial release
//	1.0.1					2025-09-08			William Veim				Added input for visibility/In use
//	1.0.2					2026-02-19			William Veim				Updated according to new quality setup
//================================================================================================================================

EXT_StateData.Sts_Visible:=Inp_Visibility;
EXT_StateData.Sts_State:=Inp_State;

IF EXT_StateData.Sts_Visible THEN
	EXT_StateData.Sts_Desc:=Inp_Desc;
ELSE
	Clear(EXT_StateData.Sts_Desc);
END_IF;

Sts_AlarmPriority:=EXT_StateData.Cfg_Quality;
Sts_AlarmState:=Inp_State AND EXT_StateData.Cfg_Alarm AND EXT_StateData.Sts_Visible;
Sts_AlarmSuffix:=Inp_Desc;

IF EXT_StateData.Sts_State AND EXT_StateData.Sts_Visible THEN
	
	//UPDATES ACTION
	CASE EXT_StateData.Cfg_Action OF
		
		0://Use value
		IF Sts_ActionState = 0 THEN
			Sts_ActionState:=0;
		END_IF;
		
		1://Hold value
		IF Sts_ActionState < 2 THEN
			Sts_ActionState:=1;
		END_IF;
		
		2://Pre defined value
		IF Sts_ActionState < 3 THEN
			Sts_ActionState:=2;
		END_IF;
		
		3://OFF (Not available in all types)
		Sts_ActionState:=3;
		
		99://Locked to OFF - Disable buttons in SCADA
		Sts_ActionState:=3;
		
	END_CASE;
	
	//UPDATES QUALITY
	CASE EXT_StateData.Cfg_Quality OF
		
		0://Diagnostic
		IF Sts_Quality = 0 OR Sts_Quality = 6 THEN
			Sts_Quality := 0;
		END_IF;
		
		1://Low
		IF Sts_Quality < 2 OR Sts_Quality = 6  THEN
			Sts_Quality:=1;
		END_IF;
		
		2://Medium (not in use)
		IF Sts_Quality < 3 OR Sts_Quality = 6 THEN
		Sts_Quality:=2;
		END_IF;
		
		3://High
		IF Sts_Quality < 4 OR Sts_Quality = 6 THEN
		Sts_Quality:=3;
		END_IF;
		
		4://Critical
		Sts_Quality:=4;
		
	END_CASE;
	
END_IF;
